# area: overloads
# hypothesis: Calling the overloaded encode function, with the str overload listed first, on an int | str value makes mypy and ty expand the union and infer bytes | str, and the runtime returns bytes for str input and str for int input.
from typing import assert_type, overload, reveal_type


@overload
def encode(x: str) -> bytes: ...


@overload
def encode(x: int) -> str: ...


def encode(x: int | str) -> bytes | str:
    if isinstance(x, str):
        return x.encode()
    return str(x)


def pick(v: int | str) -> None:
    r = encode(v)
    assert_type(r, bytes | str)
    print(r)


pick(7)
pick("hi")
reveal_type(encode)
